import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { flipBetHandler } from "../handlers/flipBetHandler";
import type { ApiError } from "../runtime/client";
import type { FactFoldRoundEntityType } from "../types/FactFoldRoundEntityType";
import type { FlipBetRequest } from "../types/FlipBetRequest";

type Data = Awaited<ReturnType<typeof flipBetHandler>>;
type Vars = { roundId: FactFoldRoundEntityType; req: FlipBetRequest };

export function useFlipBet(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => flipBetHandler(vars.roundId, vars.req),
    ...options,
  });
}
